package com.fitconnect.booking.api; import com.fitconnect.booking.service.BookingService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/bookings") public class BookingController {private final BookingService s;public BookingController(BookingService s){this.s=s;}@GetMapping public List<BookingResponse> all(){return s.all();}@GetMapping("/{id}") public BookingResponse get(@PathVariable Long id){return s.get(id);}@GetMapping("/user/{id}") public List<BookingResponse> user(@PathVariable Long id){return s.user(id);}@PostMapping public ResponseEntity<BookingResponse> create(@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody BookingRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(key,r));}@PatchMapping("/{id}/confirm") public BookingResponse confirm(@PathVariable Long id,@Valid @RequestBody ConfirmRequest r){return s.confirm(id,r);}@PatchMapping("/{id}/cancel") public BookingResponse cancel(@PathVariable Long id){return s.cancel(id);}@PatchMapping("/{id}/complete") public BookingResponse complete(@PathVariable Long id){return s.complete(id);}@GetMapping("/expired") public List<BookingResponse> expired(){return s.expired();}}
